entries[161773] = { ["name"] = "Zügel der Alabasterhyäne", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man eine Alabasterhyäne beschwört.\nBeschwört Eure Alabasterhyäne oder gibt sie wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nBenötigt Voldunai\n- Ehrfürchtig\n\n\"Diese Hyänen werden von den Voldunai eingesetzt, um sich schnell und ungesehen durch die Sande zu bewegen.\"\nVerkäufer:\nHorterin Jena\nZone:\nVol'dun\nFraktion:\nVoldunai - Ehrfürchtig\nKosten:\n10." }
entries[161774] = { ["name"] = "Zügel des Blutschwärmers der Expedition", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man einen Blutschwärmer der Expedition beschwört.\nBeschwört Euren Blutschwärmer der Expedition oder gibt ihn wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nBenötigt Talanjis Expedition\n- Ehrfürchtig\n\n\"Nachdem er beim Angriff auf die Bluttrolle zum Waisen wurde, haben Talanjis Tierführer diesen Blutschwärmer neu abgerichtet.\"\nVerkäufer:\nVersorgerin Lija\nZone:\nNazmir\nFraktion:\nTalanjis Expedition - Ehrfürchtig\nKosten:\n10." }
entries[161878] = { ["name"] = "Winziger Geldbeutel", ["text"] = "Wird beim Aufheben gebunden\n<Zum Öffnen rechtsklicken>" }
entries[161879] = { ["name"] = "Zügel des Prachtmeerseespähers", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man einen Prachtmeerseespäher beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nBenötigt Prachtmeeradmiralität\n- Ehrfürchtig\nErforderlicher Erfolg: Pfadfinder von Battle for Azeroth, Teil zwei.\n\n\"Nur wenige Greifen werden als Seespäher ausgewählt, die von Flaggschiffen der Flotte aus eingesetzt werden. Ihre Erkundungsfähigkeiten auf langen Strecken leistet einen wichtigen Beitrag zur Vorherrschaft von Kul Tiras auf See.\"\nVerkäufer:\nVersorgerin Frauke\nZone:\nDer Tiragardesund\nFraktion:\nPrachtmeeradmiralität - Ehrfürchtig\nKosten:\n90." }
