entries[161908] = { ["name"] = "Zügel des düsteren Kronsteiggreifen", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man einen düsteren Kronsteiggreifen beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nBenötigt Glutorden\n- Ehrfürchtig\nErforderlicher Erfolg: Pfadfinder von Battle for Azeroth, Teil zwei.\n\n\"Diese leisen, flinken Greifen sind häufig in den dunklen Wäldern Drustvars anzutreffen. Ihre Fähigkeit, allein oder als Reittier eingesetzt zu werden, ist nützlich für Hinterhalte und Überraschungsangriffe.\"\nVerkäufer:\nRüstmeister Alkorn\nZone:\nDrustvar\nFraktion:\nDer Glutorden - Ehrfürchtig\nKosten:\n90." }
entries[161909] = { ["name"] = "Zügel des Küstenwächters von Sturmsang", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man einen Küstenwächter von Sturmsang beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nBenötigt Die Sturmwacht\n- Ehrfürchtig\nErforderlicher Erfolg: Pfadfinder von Battle for Azeroth, Teil zwei.\n\n\"Die Küstenwächter von Sturmsang haben die Aufgabe, die See zu beobachten und gegen eintreffende Bedrohungen zu sichern. Sie fliegen stetige Patrouillen.\"\nVerkäufer:\nSchwester Liliana\nZone:\nDas Sturmsangtal\nFraktion:\nDie Sturmwacht - Ehrfürchtig\nKosten:\n90." }
entries[161910] = { ["name"] = "Zügel des nebelgrauen Streitrosses", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man ein nebelgraues Streitross beschwört.\nBeschwört Euer rußschwarzes Kronsteigstreitross oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nBenötigt Glutorden\n- Ehrfürchtig\n\n\"Diese Rösser gehören zu den ältesten Pferderassen in Kul Tiras und sind sogar viele Male im ersten Kampf gegen die Drust vorangestürmt.\"\nVerkäufer:\nRüstmeister Alkorn\nZone:\nDrustvar\nFraktion:\nDer Glutorden - Ehrfürchtig\nKosten:\n10." }
entries[161911] = { ["name"] = "Zügel des Hengsts der Admiralität", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man einen Hengst der Admiralität beschwört.\nBeschwört Euren Hengst der Admiralität oder gibt ihn wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nBenötigt Prachtmeeradmiralität\n- Ehrfürchtig\n\n\"Diese geschmeidigen weißen Hengste sind die wenigen Reittiere, die auf den Schiffen von Kul Tiras erlaubt sind.\"\nVerkäufer:\nVersorgerin Frauke\nZone:\nDer Tiragardesund\nFraktion:\nPrachtmeeradmiralität - Ehrfürchtig\nKosten:\n10." }
entries[161912] = { ["name"] = "Zügel des Apfelschimmels", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man einen Apfelschimmel beschwört.\nBeschwört Euren Apfelschimmel der Sturmwacht oder gibt ihn wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nBenötigt Die Sturmwacht\n- Ehrfürchtig\n\n\"Ein beliebtes Reittier bei den Meerespriestern, die in Sturmsang beheimatet sind.\"\nVerkäufer:\nSchwester Liliana\nZone:\nDas Sturmsangtal\nFraktion:\nDie Sturmwacht - Ehrfürchtig\nKosten:\n10." }
