entries[162123] = { ["name"] = "Missionsbericht", ["text"] = "Questgegenstand\n\"Der Bericht enthält genaue Informationen zur Mission, die Kuppensteigweide im Sturmsangtal zu erobern.\"" }
entries[162124] = { ["name"] = "Vantusrunentechnik: Uldir", ["text"] = "Rang 2\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man eine Vantusrune: Uldir effizienter herstellt.\nVerringert die erforderlichen Materialien zur Herstellung einer Vantusrune: Uldir.\nBenötigt Inschriftenkunde von Kul Tiras (100)\nVerkaufspreis:\nVantusrune: Uldir\nBenutzen: Stellt Euch auf die Energien des anvisierten Schlachtzugsbosses aus Uldir ein, was Eure Vielseitigkeit um 2078 erhöht, während Ihr diesen Boss bekämpft. Dieser Effekt hält eine ganze Woche lang an.\n\nIhr könnt nur eine Vantusrune pro Woche nutzen.\nVerkaufspreis:\nBenötigt Leichtes Pergament , Blutrote Tinte (18), Grünliche Tinte (8)" }
entries[162125] = { ["name"] = "Vantusrunentechnik: Uldir", ["text"] = "Rang 3\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man eine Vantusrune: Uldir effizienter herstellt.\nVerringert erheblich die erforderlichen Materialien zur Herstellung einer Vantusrune: Uldir.\nBenötigt Inschriftenkunde von Kul Tiras (100)\nVerkaufspreis:\nVantusrune: Uldir\nBenutzen: Stellt Euch auf die Energien des anvisierten Schlachtzugsbosses aus Uldir ein, was Eure Vielseitigkeit um 2078 erhöht, während Ihr diesen Boss bekämpft. Dieser Effekt hält eine ganze Woche lang an.\n\nIhr könnt nur eine Vantusrune pro Woche nutzen.\nVerkaufspreis:\nBenötigt Leichtes Pergament , Blutrote Tinte (15), Grünliche Tinte (6)" }
entries[162126] = { ["name"] = "Flussmuschelfleisch", ["text"] = "Wird beim Aufheben gebunden\n\"Schmeckt erstaunlich fad!\"\nVerkaufspreis:" }
entries[162127] = { ["name"] = "Flussmuschelperle", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Gewährt Wasseratmung und erhöht innerhalb von Nazmir die Bewegungsgeschwindigkeit auf dem Meeresboden um 100%.\n1 Aufladung\nVerkaufspreis:" }
entries[162128] = { ["name"] = "Rezept: Stahlhauttrank", ["text"] = "Rang 3\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man einen Stahlhauttrank effektiver herstellt.\nChance auf die Herstellung mehrerer Tränke.\nBenötigt Alchemie von Kul Tiras\n(1)\nBenötigt7. Legion\n- Respektvoll\nVerkaufspreis:\nStahlhauttrank\nBenutzen: Verleiht Eurem Körper widerstandfähige Energie, die Eure Rüstung 25 Sek. lang um 269 erhöht. (5 Min Abklingzeit)\nVerkaufspreis:\nBenötigt Meeresstängel (10), Flussknospe (8), Kristallphiole" }
entries[162129] = { ["name"] = "Rezept: Trank der Erfrischung", ["text"] = "Rang 3\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man einen Trank der Erfrischung effektiver herstellt.\nChance auf die Herstellung mehrerer Tränke.\nBenötigt Alchemie von Kul Tiras\n(1)\nBenötigt Die Sturmwacht\n- Respektvoll\nVerkaufspreis:\nTrank der Erfrischung\nBenutzen: Versetzt den Trinkenden in einen Zustand höchster Konzentration, in dem er im Verlauf von 10 Sek. bis zu ( 601 * 10) Mana regeneriert, aber wehrlos ist, bis die Konzentration gebrochen wird. (5 Min Abklingzeit)\nVerkaufspreis:\nBenötigt Sirenenpollen (10), Sternmoos (8), Kristallphiole" }
entries[162130] = { ["name"] = "Rezept: Trank der Bluteruption", ["text"] = "Rang 3\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man einen Trank der Bluteruption effektiver herstellt.\nChance auf die Herstellung mehrerer Tränke.\nBenötigt Alchemie von Kul Tiras\n(1)\nBenötigt Prachtmeeradmiralität\n- Respektvoll\nVerkaufspreis:\nTrank der Bluteruption\nBenutzen: Erfüllt Euer Blut für 25 Sek. mit Hitze, die Euren Nahkampfangriffen eine Chance gewährt, eine Blutexplosion auszulösen, die 5371 körperlichen Schaden verursacht, der gleichmäßig unter allen Gegnern in der Nähe aufgeteilt wird. (5 Min Abklingzeit)\nVerkaufspreis:\nBenötigt Sirenenpollen (8), Flussknospe (6), Kristallphiole" }
entries[162131] = { ["name"] = "Rezept: Trank des drohenden Todes", ["text"] = "Rang 3\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man einen Trank des drohenden Todes effektiver herstellt.\nChance auf die Herstellung mehrerer Tränke.\nBenötigt Alchemie von Kul Tiras\n(1)\nBenötigt Glutorden\n- Respektvoll\nVerkaufspreis:\nTrank des drohenden Todes\nBenutzen: Ermächtigt Euch für 25 Sek. mit Schattenmagie. Sie verleiht Euren Schaden verursachenden Distanzfähigkeiten eine Chance, einen Todesblitz abzufeuern, dessen Schaden sich mit der zurückgelegten Strecke erhöht und der bis zu 331209 Schattenschaden verursacht. (5 Min Abklingzeit)\nVerkaufspreis:\nBenötigt Meeresstängel (8), Sternmoos (6), Kristallphiole" }
entries[162132] = { ["name"] = "Rezept: Fläschchen der Ströme", ["text"] = "Rang 3\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man ein Fläschchen der Ströme effektiver herstellt.\nChance auf die Herstellung mehrerer Fläschchen.\nBenötigt Alchemie von Kul Tiras\n(1)\nBenötigt7. Legion\n- Respektvoll\nVerkaufspreis:\nFläschchen der Ströme\nBenutzen: Erhöht die Beweglichkeit 1 Stunde lang um 71 . Gilt sowohl als Kampfelixier als auch als Wächterelixier. Dieser Effekt hält über den Tod hinaus an. (3 Sek. Abklingzeit)\nVerkaufspreis:\nBenötigt Ankerkraut (5), Akundas Biss (10), Meeresstängel (15), Kristallphiole" }
entries[162133] = { ["name"] = "Rezept: Fläschchen der unendlichen Tiefe", ["text"] = "Rang 3\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man ein Fläschchen der unendlichen Tiefe effektiver herstellt.\nChance auf die Herstellung mehrerer Fläschchen.\nBenötigt Alchemie von Kul Tiras\n(1)\nBenötigt Die Sturmwacht\n- Respektvoll\nVerkaufspreis:\nFläschchen der unendlichen Tiefe\nBenutzen: Erhöht die Intelligenz 1 Stunde lang um 71 . Gilt sowohl als Kampfelixier als auch als Wächterelixier. Dieser Effekt hält über den Tod hinaus an. (3 Sek. Abklingzeit)\nVerkaufspreis:\nBenötigt Ankerkraut (5), Winterkuss (10), Flussknospe (15), Kristallphiole" }
entries[162134] = { ["name"] = "Rezept: Fläschchen des weiten Horizonts", ["text"] = "Rang 3\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man ein Fläschchen des weiten Horizonts effektiver herstellt.\nChance auf die Herstellung mehrerer Fläschchen.\nBenötigt Alchemie von Kul Tiras\n(1)\nBenötigt Prachtmeeradmiralität\n- Respektvoll\nVerkaufspreis:\nFläschchen des weiten Horizonts\nBenutzen: Erhöht die Ausdauer 1 Stunde lang um 107 . Gilt sowohl als Kampfelixier als auch als Wächterelixier. Dieser Effekt hält über den Tod hinaus an. (3 Sek. Abklingzeit)\nVerkaufspreis:\nBenötigt Ankerkraut (5), Winterkuss (10), Sternmoos (15), Kristallphiole" }
entries[162135] = { ["name"] = "Rezept: Fläschchen des Tiefensogs", ["text"] = "Rang 3\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man ein Fläschchen des Tiefensogs effektiver herstellt.\nChance auf die Herstellung mehrerer Fläschchen.\nBenötigt Alchemie von Kul Tiras\n(1)\nBenötigt Glutorden\n- Respektvoll\nVerkaufspreis:\nFläschchen des Tiefensogs\nBenutzen: Erhöht die Stärke 1 Stunde lang um 71 . Gilt sowohl als Kampfelixier als auch als Wächterelixier. Dieser Effekt hält über den Tod hinaus an. (3 Sek. Abklingzeit)\nVerkaufspreis:\nBenötigt Ankerkraut (5), Akundas Biss (10), Sirenenpollen (15), Kristallphiole" }
entries[162136] = { ["name"] = "Rezept: Endlose Tinktur des erneuerten Kampfgeists", ["text"] = "Rang 3\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man eine endlose Tinktur des erneuerten Kampfgeists effizienter herstellt.\nChance auf die Herstellung mehrerer Tinkturen.\nBenötigt Alchemie von Kul Tiras\n(1)\nBenötigt Tortollanische Sucher\n- Respektvoll\nVerkaufspreis:\nEndlose Tinktur des erneuerten Kampfgeists\nWird beim Anlegen gebunden\nEinzigartig anlegbar\nSchmuck\n+ 9 Vielseitigkeit\nAnlegen: Stellt 696 Gesundheit wieder her, wenn Ihr ein Ziel tötet, das Erfahrung oder Ehre gewährt.\nVerkaufspreis:\nBenötigt Sirenenpollen (18), Flussknospe (18), Expulsom , Kristallphiole\nOptionale Reagenzien: [] (#47)" }
entries[162137] = { ["name"] = "Rezept: Alchemistenstein der Sirene", ["text"] = "Rang 3\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man einen Alchemistenstein der Sirene effizienter herstellt.\nVerringert die erforderlichen Materialien zur Herstellung eines Alchemistensteins der Sirene noch weiter.\nBenötigt Alchemie von Kul Tiras\n(1)\nBenötigt Tortollanische Sucher\n- Respektvoll\nVerkaufspreis:\nAlchemistenstein der Sirene\nWird beim Anlegen gebunden\nEinzigartig anlegbar\nSchmuck\n+ 9 Vielseitigkeit\nAnlegen: Bei hervorgerufener Heilung oder verursachtem Schaden besteht eine Chance, dass sich Eure Stärke, Beweglichkeit oder Intelligenz 15 Sek. lang um 23 erhöht. Es wird stets Euer höchster Wert gewählt.\nAnlegen: Erhöht die Effekte, die Heil- und Manatränke auf den Träger haben, um 40%. Dieser Effekt ist nicht stapelbar.\nBenötigt Alchemie von Kul Tiras\n(1)\n\"Kann anstelle eines Steins der Weisen für Transmutationen verwendet werden.\"\nVerkaufspreis:\nBenötigt Meeresstängel (16), Sternmoos (16), Expulsom\nOptionale Reagenzien: [] (#47)" }
entries[162138] = { ["name"] = "Rezept: Endlose Tinktur der bruchstückhaften Macht", ["text"] = "Rang 3\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man eine endlose Tinktur der bruchstückhaften Macht effizienter herstellt.\nChance auf die Herstellung mehrerer Tinkturen.\nBenötigt Alchemie von Kul Tiras\n(1)\nBenötigt7. Legion\n- Respektvoll\nVerkaufspreis:\nEndlose Tinktur der bruchstückhaften Macht\nWird beim Anlegen gebunden\nEinzigartig anlegbar\nSchmuck\n+ 9 Vielseitigkeit\nBenutzen: Kopiert den Stärkungseffekt des aktuellen Fläschchens des Trägers, jedoch nur zu einem Bruchteil der Wirksamkeit. Hält 12 Sek. lang an. (1 Min Abklingzeit)\nVerkaufspreis:\nBenötigt Fläschchen der Ströme , Fläschchen der unendlichen Tiefe , Fläschchen des weiten Horizonts , Fläschchen des Tiefensogs , Expulsom (6)" }
entries[162139] = { ["name"] = "Rezept: Wallender Alchemistenstein", ["text"] = "Rang 3\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man einen wallenden Alchemistenstein effizienter herstellt.\nVerringert die erforderlichen Materialien zur Herstellung eines wallenden Alchemistensteins noch weiter.\nBenötigt Alchemie von Kul Tiras\n(1)\nBenötigt7. Legion\n- Respektvoll\nVerkaufspreis:\nWallender Alchemistenstein\nWird beim Anlegen gebunden\nEinzigartig anlegbar\nSchmuck\n+ 9 Vielseitigkeit\nAnlegen: Bei hervorgerufener Heilung oder verursachtem Schaden besteht eine Chance, dass sich Eure Stärke, Beweglichkeit oder Intelligenz 15 Sek. lang um 24 erhöht. Es wird stets Euer höchster Wert gewählt.\nAnlegen: Erhöht die Effekte, die Heil- und Manatränke auf den Träger haben, um 40%. Dieser Effekt ist nicht stapelbar.\nBenötigt Alchemie von Kul Tiras\n(1)\n\"Kann anstelle eines Steins der Weisen für Transmutationen verwendet werden.\"\nVerkaufspreis:\nBenötigt Ankerkraut (12), Akundas Biss (32), Winterkuss (32), Expulsom (16)" }
entries[162140] = { ["name"] = "Kampferprobtes Rüstungsset", ["text"] = "Das Arathihochland\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Verstärkt die Rüstung eines Verbündeten und verringert für 10 Min. seinen erlittenen Schaden um 10%.\n5 Aufladungen" }
entries[162141] = { ["name"] = "Trank des Kampfgeschicks", ["text"] = "Das Arathihochland\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Gewährt dem Trinkenden größere Konzentration im Kampf und erhöht seinen verursachten Schaden für 10 Min. um 50%." }
entries[162142] = { ["name"] = "Trank der Wiederherstellung", ["text"] = "Das Arathihochland\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Gewährt dem Trinkenden größere Konzentration beim Wirken wiederherstellender Zauber und erhöht seine Heilung für 10 Min. um 20%." }
entries[162143] = { ["name"] = "Trank der Wiederherstellung", ["text"] = "Das Arathihochland\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Gewährt dem Trinkenden größere Konzentration beim Wirken wiederherstellender Zauber und erhöht seine Heilung für 10 Min. um 20%." }
entries[162253] = { ["name"] = "Marineaufzeichnungen", ["text"] = "Questgegenstand\nEinzigartig\n\"Diese Papiere enthalten Details zu einigen Schiffen der Zandalariflotte, einschließlich ihrer Routen.\"" }
entries[162254] = { ["name"] = "Rezept: Manatrank der Küste", ["text"] = "Rang 3\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man einen Manatrank der Küste effizienter herstellt.\nChance auf die Herstellung mehrerer Tränke.\nBenötigt Alchemie von Kul Tiras\n(1)\nBenötigt Prachtmeeradmiralität\n- Respektvoll\nVerkaufspreis:\nManatrank der Küste\nBenutzen: Stellt 2667 Mana wieder her. (5 Min Abklingzeit)\nVerkaufspreis:\nBenötigt Flussknospe (2), Kristallphiole" }
entries[162255] = { ["name"] = "Rezept: Heiltrank der Küste", ["text"] = "Rang 3\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man einen Heiltrank der Küste effizienter herstellt.\nChance auf die Herstellung mehrerer Tränke.\nBenötigt Alchemie von Kul Tiras\n(1)\nBenötigt Die Sturmwacht\n- Respektvoll\nVerkaufspreis:\nHeiltrank der Küste\nBenutzen: Stellt 8000 Gesundheit wieder her. (5 Min Abklingzeit)\nVerkaufspreis:\nBenötigt Sirenenpollen (2), Kristallphiole" }
entries[162256] = { ["name"] = "Rezept: Verjüngungstrank der Küste", ["text"] = "Rang 3\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man einen Verjüngungstrank der Küste effizienter herstellt.\nChance auf die Herstellung mehrerer Tränke.\nBenötigt Alchemie von Kul Tiras\n(1)\nBenötigt Glutorden\n- Respektvoll\nVerkaufspreis:\nVerjüngungstrank der Küste\nBenutzen: Stellt 8000 Gesundheit und 2000 Mana wieder her. (5 Min Abklingzeit)\nVerkaufspreis:\nBenötigt Heiltrank der Küste , Manatrank der Küste" }
entries[162257] = { ["name"] = "Rezept: Demitris Destillat der Täuschung", ["text"] = "Rang 3\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man Demitris Destillat der Täuschung effizienter herstellt.\nChance auf die Herstellung mehrerer Destillate.\nBenötigt Alchemie von Kul Tiras\n(1)\nVerkaufspreis:\nDemitris Destillat der Täuschung\nBenutzen: Gewährt dem Trinkenden 18 Sek. lang Unsichtbarkeit. Funktioniert nicht über Stufe 50. (5 Min Abklingzeit)\nVerkaufspreis:\nBenötigt Sandschleicher (5), Meeresstängel (5), Kristallphiole" }
entries[162258] = { ["name"] = "Rezept: Trank der Leichtfüßigkeit", ["text"] = "Rang 3\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man einen Trank der Leichtfüßigkeit effizienter herstellt.\nChance auf die Herstellung mehrerer Tränke.\nBenötigt Alchemie von Kul Tiras\n(1)\nVerkaufspreis:\nTrank der Leichtfüßigkeit\nBenutzen: Erhöht die Bewegungsgeschwindigkeit 8 Sek. lang um 150%. Funktioniert nicht über Stufe 50. (5 Min Abklingzeit)\nVerkaufspreis:\nBenötigt Sternmoos (10), Kristallphiole" }
entries[162259] = { ["name"] = "Rezept: Meeresnebeltrank", ["text"] = "Rang 3\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man einen Meeresnebeltrank effizienter herstellt.\nChance auf die Herstellung mehrerer Tränke.\nBenötigt Alchemie von Kul Tiras\n(1)\nVerkaufspreis:\nMeeresnebeltrank\nBenutzen: Verwandelt den Trinkenden in eine Wolke, was langsamen Fall und das Schweben über Wasser gewährt. Hält 1 Min. lang an. (5 Min Abklingzeit)\nVerkaufspreis:\nBenötigt Meeresstängel (10), Kristallphiole" }
entries[162260] = { ["name"] = "Rezept: Trank der Verhüllung", ["text"] = "Rang 3\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man einen Trank der Verhüllung effizienter herstellt.\nChance auf die Herstellung mehrerer Tränke.\nBenötigt Alchemie von Kul Tiras\n(1)\nVerkaufspreis:\nTrank der Verhüllung\nBenutzen: Bewahrt den Trinkenden davor, entdeckt zu werden, solange er stillsteht. Hält 3 Min. lang an. (5 Min Abklingzeit)\nVerkaufspreis:\nBenötigt Sirenenpollen (10), Kristallphiole" }
