entries[162331] = { ["name"] = "Bauplan: B.R.U.T.Z.L.", ["text"] = "Rang 3\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man einen B.R.U.T.Z.L. effizienter herstellt.\nVerringert erheblich die erforderlichen Materialien zur Herstellung eines B.R.U.T.Z.L.\n\nChance, mehrere Bomben herzustellen.\nBenötigt Ingenieurskunst von Kul Tiras (1)\nVerkaufspreis:\nB.R.U.T.Z.L.\nBenutzen: Fügt allen Gegnern in einem Radius von 5 Metern 4180 Feuerschaden zu. (5 Min Abklingzeit)\n\"Blitz-Röstungs-Ultra-Thermo-Zünd-Lader. Explizit NICHT für Kochzwecke geeignet!\"\nVerkaufspreis:\nBenötigt Moneliterz (4), Chemische Sprengkapsel (2), Isoliertes Kabel (4)" }
entries[162332] = { ["name"] = "Bauplan: Thermobeschleunigter Seuchenverbreiter", ["text"] = "Rang 3\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man einen thermobeschleunigten Seuchenverbreiter effizienter herstellt.\nVerringert erheblich die erforderlichen Materialien zur Herstellung eines thermobeschleunigten Seuchenverbreiters.\n\nChance, mehrere Bomben herzustellen.\nBenötigt Ingenieurskunst von Kul Tiras (1)\nVerkaufspreis:\nThermobeschleunigter Seuchenverbreiter\nBenutzen: Erzeugt einen vergifteten Bereich, der allen Gegnern alle 3 Sek. 1003 Schaden zufügt, solange sie sich darin aufhalten. Hält 15 Sek. lang an. (5 Min Abklingzeit)\nBenötigt Moneliterz (4), Chemische Sprengkapsel (2), Isoliertes Kabel (4)" }
