entries[162336] = { ["name"] = "Bauplan: Neurologische Lähmungsbombe", ["text"] = "Rang 3\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man eine neurologische Lähmungsbombe effizienter herstellt.\nBenötigt Ingenieurskunst von Kul Tiras (1)\nBenötigt Prachtmeeradmiralität\n- Respektvoll\nVerkaufspreis:" }
entries[162337] = { ["name"] = "Bauplan: Organische Diskombobulierungsgranate", ["text"] = "Rang 3\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man eine organische Diskombobulierungsgranate effizienter herstellt.\nVerringert erheblich die erforderlichen Materialien zur Herstellung einer organischen Diskombobulierungsgranate.\n\nChance, mehrere Bomben herzustellen.\nBenötigt Ingenieurskunst von Kul Tiras (1)\nBenötigt Die Sturmwacht\n- Respektvoll\nVerkaufspreis:\nOrganische Diskombobulierungsgranate\nBenutzen: Wirft eine Bombe, die bei ihrer Detonation 5 mechanische Schafe beschwört. Gegner, die mit den Schafen in Kontakt kommen, werden für 20 Sek. verwandelt. Funktioniert nicht bei Zielen über Stufe 50. (1 Min Abklingzeit)\nVerkaufspreis:\nBenötigt Moneliterz (4), Chemische Sprengkapsel (2), Isoliertes Kabel (4)" }
entries[162338] = { ["name"] = "Bauplan: Elektrogezündete Schlafbombe", ["text"] = "Rang 3\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man eine elektrogezündete Schlafbombe effizienter herstellt.\nBenötigt Ingenieurskunst von Kul Tiras (1)\nVerkaufspreis:" }
entries[162339] = { ["name"] = "Bauplan: XA-1000 Wellengleiter", ["text"] = "Rang 3\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man einen XA-1000 Wellengleiter effizienter herstellt.\nVerringert erheblich die erforderlichen Materialien zur Herstellung eines XA-1000 Wellengleiters.\nBenötigt Ingenieurskunst von Kul Tiras (1)\nVerkaufspreis:\nXA-1000 Wellengleiter\nBenutzen: Setzt ein Boot ein, das sofort losfährt und sich 25 Sek. lang über das Wasser bewegt. Funktioniert nicht an Land. (30 Sek. Abklingzeit)\nVerkaufspreis:\nBenötigt Moneliterz (10), Sturmsilbererz (5), Isoliertes Kabel (4)" }
entries[162340] = { ["name"] = "Bauplan: Elektroschocker zur Reittiermotivierung", ["text"] = "Rang 3\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man einen Elektroschocker zur Reittiermotivierung effizienter herstellt.\nVerringert erheblich die erforderlichen Materialien zur Herstellung eines Elektroschockers zur Reittiermotivierung.\nBenötigt Ingenieurskunst von Kul Tiras (1)\nVerkaufspreis:\nElektroschocker zur Reittiermotivierung\nBenutzen: Erhöht 10 Sek. lang die Reitgeschwindigkeit um 10%. Bis zu 5-mal stapelbar. Durch erhöhte Motivation kann Euer Reittier desorientiert werden.\n\nNicht mit anderen Effekten zur Erhöhung der Reitgeschwindigkeit stapelbar.\n50 Aufladungen\n\"Bei der Konzipierung dieses Geräts kamen einige Tiere zu Schaden. Es geht ihnen aber schon wieder besser... den meisten zumindest.\"\nVerkaufspreis:\nBenötigt Moneliterz (8), Sturmsilbererz (4), Isoliertes Kabel (6)" }
entries[162341] = { ["name"] = "Bauplan: Interdimensionales Begleiterrepositorium", ["text"] = "Rang 3\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man ein interdimensionales Begleiterrepositorium effizienter herstellt.\nVerringert erheblich die erforderlichen Materialien zur Herstellung eines interdimensionalen Begleiterrepositoriums.\nBenötigt Ingenieurskunst von Kul Tiras (1)\nBenötigt Die Sturmwacht\n- Respektvoll\nVerkaufspreis:\nInterdimensionales Begleiterrepositorium\nBenutzen: Beschwört einen tragbaren Stallmeister, mit dem Jäger bis zu 2 Min. lang interagieren können.\nVerkaufspreis:\nBenötigt Moneliterz (5), Sturmsilbererz (4), Isoliertes Kabel (5)" }
entries[162342] = { ["name"] = "Bauplan: Stationärer Umkleider", ["text"] = "Rang 3\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man einen stationären Umkleider effizienter herstellt.\nVerringert erheblich die erforderlichen Materialien zur Herstellung eines stationären Umkleiders.\nBenötigt Ingenieurskunst von Kul Tiras (1)\nBenötigt Die Sturmwacht\n- Respektvoll\nVerkaufspreis:\nStationärer Umkleider\nBenutzen: Beschwört ein Gerät, mit dem Ihr das Aussehen Eurer Rüstung verändern könnt. Das Gerät bleibt bis zu 2 Min. lang bestehen.\n\"Hinweis: Aufgrund der Funktionsweise dieses Geräts sind leichte Kopfschmerzen, Übelkeit sowie Wechsel von Volkszugehörigkeit und/oder Geschlecht nicht auszuschließen. Mit Vorsicht zu verwenden.\"\nVerkaufspreis:\nBenötigt Moneliterz (5), Sturmsilbererz (4), Isoliertes Kabel (5)" }
entries[162343] = { ["name"] = "Bauplan: Zielfernrohr des Ausgucks", ["text"] = "Rang 3\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man ein Zielfernrohr des Ausgucks effizienter herstellt.\nVerringert erheblich die erforderlichen Materialien zur Herstellung eines Zielfernrohrs des Ausgucks.\nBenötigt Ingenieurskunst von Kul Tiras (1)\nVerkaufspreis:\nZielfernrohr des Ausgucks\nBenutzen: Bringt dauerhaft ein Zielfernrohr an einer Distanzwaffe an, sodass manchmal Euer kritischer Trefferwert 12 Sek. lang um 194 erhöht wird, wenn Ihr Distanzschaden verursacht.\n\nDurch das Anbringen dieser Vorrichtung an eine Distanzwaffe wird diese seelengebunden.\nVerkaufspreis:\nBenötigt Moneliterz (10), Sturmsilbererz (5)" }
entries[162344] = { ["name"] = "Bauplan: Monelitzielfernrohr des Eifers", ["text"] = "Rang 3\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man ein Monelitzielfernrohr des Eifers effizienter herstellt.\nVerringert erheblich die erforderlichen Materialien zur Herstellung eines Monelitzielfernrohrs des Eifers.\nBenötigt Ingenieurskunst von Kul Tiras (1)\nBenötigt7. Legion\n- Respektvoll\nVerkaufspreis:\nMonelitzielfernrohr des Eifers\nBenutzen: Bringt dauerhaft eine spezielle Vorrichtung an einer Distanzwaffe an, sodass manchmal das Tempo 12 Sek. lang um 194 erhöht wird, wenn Ihr Distanzschaden verursacht.\n\nDurch das Anbringen der Vorrichtung an einer Distanzwaffe wird diese seelengebunden.\nVerkaufspreis:\nBenötigt Moneliterz (10), Sturmsilbererz (5)" }
entries[162345] = { ["name"] = "Bauplan: Präzisionsgesinnungswandler", ["text"] = "Rang 3\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man einen Präzisionsgesinnungswandler effizienter herstellt.\nVerringert erheblich die erforderlichen Materialien zur Herstellung eines Präzisionsgesinnungswandlers.\nBenötigt Ingenieurskunst von Kul Tiras (1)\nBenötigt7. Legion\n- Respektvoll\nVerkaufspreis:\nPräzisionsgesinnungswandler\nWird beim Anlegen gebunden\nEinhändig Streitkolben\n4 - 5 Schaden Geschwindigkeit 2.60\n(1.7 Schaden pro Sekunde)\n+18 Intelligenz\n+5 Ausdauer\nHaltbarkeit 110 / 110\n\"Die optimale Nutzung sieht Hiebe vor, bis das Ziel keine Widerrede mehr bieten kann.\"\nVerkaufspreis:\nBenötigt Sturmsilbererz (20), Platinerz (8), Expulsom (5)\nOptionale Reagenzien: [] (#49)" }
entries[162346] = { ["name"] = "Bauplan: Präzise abgestimmter Sturmstahlvernichter", ["text"] = "Rang 3\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man einen präzise abgestimmten Sturmstahlvernichter effizienter herstellt.\nVerringert erheblich die erforderlichen Materialien zur Herstellung eines präzise abgestimmten Sturmstahlvernichters.\nBenötigt Ingenieurskunst von Kul Tiras (1)\nBenötigt7. Legion\n- Respektvoll\nVerkaufspreis:\nHorde\nPräzise abgestimmter Sturmstahlvernichter\nWird beim Anlegen gebunden\nDistanz Schusswaffe\n14 Schaden Geschwindigkeit 3.00\n(4.7 Schaden pro Sekunde)\n+6 Beweglichkeit\n+9 Ausdauer\nHaltbarkeit 100 / 100\nVerkaufspreis:\nAllianz\nPräzise abgestimmter Sturmstahlvernichter\nWird beim Anlegen gebunden\nDistanz Schusswaffe\n14 Schaden Geschwindigkeit 3.00\n(4.7 Schaden pro Sekunde)\n+6 Beweglichkeit\n+9 Ausdauer\nHaltbarkeit 100 / 100\nVerkaufspreis:\nBenötigt Sturmsilbererz (20), Platinerz (8), Chemische Sprengkapsel (5), Expulsom (5)\nOptionale Reagenzien: [] (#49)" }
entries[162347] = { ["name"] = "Kelseys Wasserläufer", ["text"] = "Questgegenstand\nEinzigartig\nBenutzen: Kelsey Stahlfunkens Spezialstiefel gestatten es Euch, auf Wasser zu wandeln... hoffentlich." }
entries[162352] = { ["name"] = "Technik: Graviertes Gefäß des Mystizismus", ["text"] = "Rang 3\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man ein graviertes Gefäß des Mystizismus effizienter herstellt.\nVerringert erheblich die erforderlichen Materialien zur Herstellung eines gravierten Gefäßes des Mystizismus.\nBenötigt Inschriftenkunde von Kul Tiras (1)\nBenötigt Tortollanische Sucher\n- Respektvoll\nVerkaufspreis:\nHorde\nGraviertes Gefäß des Mystizismus\nWird beim Anlegen gebunden\nIn Schildhand geführt\n+10 Intelligenz\n+5 Ausdauer\nVerkaufspreis:\nAllianz\nGraviertes Gefäß des Mystizismus\nWird beim Anlegen gebunden\nIn Schildhand geführt\n+10 Intelligenz\n+5 Ausdauer\nVerkaufspreis:\nBenötigt Leichtes Pergament (50), Blutrote Tinte (20), Grünliche Tinte (8), Expulsom\nOptionale Reagenzien: [] (#49)" }
