entries[162443] = { ["name"] = "Muster: Schlachtflagge: Geist der Freiheit", ["text"] = "Rang 3\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man eine Schlachtflagge: Geist der Freiheit effizienter herstellt.\nVerringert erheblich die erforderlichen Materialien zur Herstellung einer Schlachtflagge: Geist der Freiheit.\nBenötigt Schneiderei von Kul Tiras (1)\nVerkaufspreis:\nSchlachtflagge: Geist der Freiheit\nBenutzen: Stellt eine Flagge auf dem Schlachtfeld auf, die die Dauer von Kontrollverlusteffekten bei Verbündeten innerhalb von 15 Metern verringert. Hält 30 Sek. lang an.\n\nKann nur in Kul Tiras, Zandalar und ungewerteten Schlachtfeldern eingesetzt werden. (5 Min Abklingzeit)\nBenötigt Gischtvernebeltes Leinen (8), Bestickter Tiefseesatin (5), Nylonfaden (16)" }
entries[162444] = { ["name"] = "Muster: Schlachtflagge: Phalanxverteidigung", ["text"] = "Rang 3\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man eine Schlachtflagge: Phalanxverteidigung effizienter herstellt.\nVerringert erheblich die erforderlichen Materialien zur Herstellung einer Schlachtflagge: Phalanxverteidigung.\nBenötigt Schneiderei von Kul Tiras (1)\nVerkaufspreis:\nSchlachtflagge: Phalanxverteidigung\nBenutzen: Stellt eine Flagge auf dem Schlachtfeld auf, die den erlittenen Schaden von Verbündeten innerhalb von 15 Metern um 15% verringert. Hält 30 Sek. lang an.\n\nKann nur in Kul Tiras, Zandalar und ungewerteten Schlachtfeldern eingesetzt werden. (5 Min Abklingzeit)\nBenötigt Gischtvernebeltes Leinen (8), Bestickter Tiefseesatin (5), Nylonfaden (16)" }
entries[162445] = { ["name"] = "Muster: Schlachtflagge: Ansporn", ["text"] = "Rang 3\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man eine Schlachtflagge: Ansporn effizienter herstellt.\nVerringert erheblich die erforderlichen Materialien zur Herstellung einer Schlachtflagge: Ansporn.\nBenötigt Schneiderei von Kul Tiras (1)\nVerkaufspreis:\nSchlachtflagge: Ansporn\nBenutzen: Macht eine Schlachtenflagge an Eurem Rücken fest, die für 15 Sek. Eure Reitgeschwindigkeit und die Eurer Gruppenmitglieder innerhalb von 10 Metern um 15% erhöht.\n\nKann nur beritten eingesetzt werden.\n\nKann nur in Kul Tiras, Zandalar und ungewerteten Schlachtfeldern eingesetzt werden. (5 Min Abklingzeit)\nBenötigt Gischtvernebeltes Leinen (8), Bestickter Tiefseesatin (5), Nylonfaden (16)" }
