entries[162518] = { ["name"] = "Mystisches Fläschchen", ["text"] = "Herbeigezauberter Gegenstand\nEinzigartig: Gildenfläschchen (1)\nBenutzen: Gewährt den Effekt eines Fläschchens basierend auf Eurer Klasse und Euren Talenten. Hält 1 Stunde lang und über den Tod hinaus an. (3 Sek. Abklingzeit)" }
entries[162519] = { ["name"] = "Mystischer Kessel", ["text"] = "Wird an Kriegsmeute gebunden\nBenutzen: Stellt einen Kessel her, der von Schlachtzugsmitgliedern benutzt werden kann, um an ein Fläschchen entsprechend ihrer Klasse und ihren Talenten zu gelangen. Der Kessel hat 30 Anwendungen und bleibt 10 Min. lang bestehen.\nVerkaufspreis:" }
entries[162520] = { ["name"] = "Rezept: Mystischer Kessel", ["text"] = "Rang 2\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man einen mystischen Kessel effektiver herstellt.\nVerringert die erforderlichen Materialien zur Herstellung eines mystischen Kessels.\nBenötigt Alchemie von Kul Tiras\n(1)\nVerkaufspreis:\nMystischer Kessel\nWird an Kriegsmeute gebunden\nBenutzen: Stellt einen Kessel her, der von Schlachtzugsmitgliedern benutzt werden kann, um an ein Fläschchen entsprechend ihrer Klasse und ihren Talenten zu gelangen. Der Kessel hat 30 Anwendungen und bleibt 10 Min. lang bestehen.\nVerkaufspreis:\nBenötigt Fläschchen der unendlichen Tiefe (3), Fläschchen der Ströme (3), Fläschchen des Tiefensogs (3), Fläschchen des weiten Horizonts (3), Expulsom (3), Hydrokern" }
