entries[162623] = { ["name"] = "Foliant der Verhexung: Sehnenreißer der Zandalari", ["text"] = "Wird beim Aufheben gebunden\nKlassen: Schamane\nBenutzen: Lehrt 'Verhexen: Sehnenreißer der Zandalari'.\nVerwandelt den Gegner für 1 Min. in einen Sehnenreißer der Zandalari. Während das Ziel verhext ist, ist es handlungsunfähig und kann weder angreifen noch Zauber wirken. Schaden kann den Effekt beenden. Maximal 1 Ziel. Kann nur auf Humanoide und Wildtiere angewandt werden.\nBenötigt Zandalariimperium\n- Respektvoll\nVerkaufspreis:" }
entries[162624] = { ["name"] = "Foliant der Verhexung: Weidenköter", ["text"] = "Wird beim Aufheben gebunden\nKlassen: Schamane\nBenutzen: Lehrt 'Verhexen: Weidenköter'.\nVerwandelt den Gegner für 1 Min. in einen Weidenköter. Während das Ziel verhext ist, ist es handlungsunfähig und kann weder angreifen noch Zauber wirken. Schaden kann den Effekt beenden. Maximal 1 Ziel. Kann nur auf Humanoide und Wildtiere angewandt werden.\nBenötigt Glutorden\n- Respektvoll\nVerkaufspreis:" }
entries[162625] = { ["name"] = "Foliant der Verwandlung: Terrorhorn", ["text"] = "Wird beim Aufheben gebunden\nKlassen: Magier\nBenutzen: Lehrt 'Verwandlung: Terrorhorn'.\nVerwandelt den Gegner in ein Terrorhornjunges, das 1 Min. lang handlungsunfähig umherirrt. In diesem Zustand kann das Opfer nicht agieren, regeneriert aber seine Gesundheit sehr schnell. Schaden beendet den Effekt ab. Es kann nur jeweils 1 Ziel betroffen sein.\n\nWirkt nur bei Tieren, Humanoiden und Kleintieren. [ Glyphe 'Kleintierverwandlung' : Bei Kleintieren kann der Zauber mehrere Ziele verwandeln, und die Verwandlung hält 1 Tag lang an ]\nBenötigt Zandalariimperium\n- Respektvoll\nVerkaufspreis:" }
entries[162626] = { ["name"] = "Foliant der Verwandlung: Hummel", ["text"] = "Wird beim Aufheben gebunden\nKlassen: Magier\nBenutzen: Lehrt 'Verwandlung: Hummel'.\nVerwandelt den Gegner in eine Hummel, die 1 Min. lang handlungsunfähig umherirrt. In diesem Zustand kann das Opfer nicht agieren, regeneriert aber seine Gesundheit sehr schnell. Schaden beendet den Effekt. Es kann nur jeweils 1 Ziel betroffen sein.\n\nWirkt nur bei Tieren, Humanoiden und Kleintieren. [ Glyphe 'Kleintierverwandlung' : Bei Kleintieren kann der Zauber mehrere Ziele verwandeln, und die Verwandlung hält 1 Tag lang an ]\nBenötigt Die Sturmwacht\n- Respektvoll\nVerkaufspreis:" }
