entries[162668] = { ["name"] = "Pläne: Zauberklinge des ehrenhaften Kämpfers", ["text"] = "Rang 2\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man eine Zauberklinge des ehrenhaften Kämpfers effizienter herstellt.\nVerringert die erforderlichen Materialien zur Herstellung einer Zauberklinge des ehrenhaften Kämpfers.\nBenötigt Schmiedekunst von Kul Tiras (1)\nVerkaufspreis:\nAllianz\nZauberklinge des ehrenhaften Kämpfers\nWird beim Anlegen gebunden\nEinhändig Dolch\n2 - 4 Schaden Geschwindigkeit 1.80\n(1.7 Schaden pro Sekunde)\n+18 Intelligenz\n+5 Ausdauer\nHaltbarkeit 65 / 65\nVerkaufspreis:\nHorde\nZauberklinge des ehrenhaften Kämpfers\nWird beim Anlegen gebunden\nEinhändig Dolch\n2 - 4 Schaden Geschwindigkeit 1.80\n(1.7 Schaden pro Sekunde)\n+18 Intelligenz\n+5 Ausdauer\nHaltbarkeit 65 / 65\nVerkaufspreis:\nBenötigt Sturmsilbererz (36), Elementarfluxus (10)\nOptionale Reagenzien: [] (#47)" }
entries[162669] = { ["name"] = "Pläne: Zauberklinge des ehrenhaften Kämpfers", ["text"] = "Rang 3\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man eine Zauberklinge des ehrenhaften Kämpfers effizienter herstellt.\nVerringert erheblich die erforderlichen Materialien zur Herstellung einer Zauberklinge des ehrenhaften Kämpfers.\nBenötigt Schmiedekunst von Kul Tiras (1)\nVerkaufspreis:\nAllianz\nZauberklinge des ehrenhaften Kämpfers\nWird beim Anlegen gebunden\nEinhändig Dolch\n2 - 4 Schaden Geschwindigkeit 1.80\n(1.7 Schaden pro Sekunde)\n+18 Intelligenz\n+5 Ausdauer\nHaltbarkeit 65 / 65\nVerkaufspreis:\nHorde\nZauberklinge des ehrenhaften Kämpfers\nWird beim Anlegen gebunden\nEinhändig Dolch\n2 - 4 Schaden Geschwindigkeit 1.80\n(1.7 Schaden pro Sekunde)\n+18 Intelligenz\n+5 Ausdauer\nHaltbarkeit 65 / 65\nVerkaufspreis:\nBenötigt Sturmsilbererz (30), Elementarfluxus (8)\nOptionale Reagenzien: [] (#47)" }
entries[162670] = { ["name"] = "Pläne: Sturmstahlsäbel", ["text"] = "Rang 3\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man einen Sturmstahlsäbel effizienter herstellt.\nVerringert erheblich die erforderlichen Materialien zur Herstellung eines Sturmstahlsäbels.\nBenötigt Schmiedekunst von Kul Tiras (1)\nBenötigt7. Legion\n- Respektvoll\nVerkaufspreis:\nAllianz\nSturmstahlsäbel\nWird beim Anlegen gebunden\nEinhändig Schwert\n6 - 12 Schaden Geschwindigkeit 2.60\n(3.5 Schaden pro Sekunde)\n+3 Stärke\n+5 Ausdauer\nHaltbarkeit 90 / 90\nVerkaufspreis:\nHorde\nSturmstahlsäbel\nWird beim Anlegen gebunden\nEinhändig Schwert\n6 - 12 Schaden Geschwindigkeit 2.60\n(3.5 Schaden pro Sekunde)\n+3 Stärke\n+5 Ausdauer\nHaltbarkeit 90 / 90\nVerkaufspreis:\nBenötigt Sturmsilbererz (22), Platinerz (10), Elementarfluxus (12), Expulsom\nOptionale Reagenzien: [] (#48)" }
