entries[162716] = { ["name"] = "Formel: Ring - Pakt des kritischen Trefferwerts", ["text"] = "Rang 3\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man 'Pakt des kritischen Trefferwerts' effizienter verzaubert.\nEinen Ring dauerhaft verzaubern, sodass der kritische Trefferwert um 19 erhöht wird. Materialbedarf erheblich verringert.\nBenötigt Verzauberkunst von Kul Tiras (1)\nBenötigt Die Eidgebundenen\n- Respektvoll\nVerkaufspreis:" }
