entries[162720] = { ["name"] = "Formel: Zauberszepter des Verzauberers", ["text"] = "Rang 3\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man ein Zauberszepter des Verzauberers effizienter herstellt.\nVerringert erheblich die erforderlichen Materialien zur Herstellung eines Zauberszepters des Verzauberers.\nBenötigt Verzauberkunst von Kul Tiras (1)\nBenötigt Die Eidgebundenen\n- Respektvoll\nVerkaufspreis:\nHorde\nZauberszepter des Verzauberers\nWird beim Anlegen gebunden\nDistanz Zauberstab\n2 - 4 Naturschaden Geschwindigkeit 2.00\n(1.5 Schaden pro Sekunde)\n+18 Intelligenz\n+5 Ausdauer\nHaltbarkeit 110 / 110\nVerkaufspreis:\nAllianz\nZauberszepter des Verzauberers\nWird beim Anlegen gebunden\nDistanz Zauberstab\n2 - 4 Schattenschaden Geschwindigkeit 2.00\n(1.5 Schaden pro Sekunde)\n+18 Intelligenz\n+5 Ausdauer\nHaltbarkeit 110 / 110\nVerkaufspreis:\nBenötigt Sternenholz , Umbralsplitter (6), Expulsom\nOptionale Reagenzien: [] (#47)" }
entries[162721] = { ["name"] = "Formel: Waffe - Unbeirrbare Navigation", ["text"] = "Rang 3\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man 'Unbeirrbare Navigation' effizienter verzaubert.\nEine Waffe dauerhaft verzaubern, sodass manchmal Eure Rüstung 30 Sek. lang um 1 erhöht wird. Dieser Effekt ist bis zu 5-mal stapelbar. Beim Erreichen von 5 Stapeln werden alle Stapel verbraucht und Eure Rüstung wird 10 Sek. lang um 9 erhöht.\n\nMaterialbedarf erheblich verringert.\nBenötigt Verzauberkunst von Kul Tiras (1)\nBenötigt Zandalariimperium\n- Respektvoll\nVerkaufspreis:" }
entries[162722] = { ["name"] = "Formel: Waffe - Tödliche Navigation", ["text"] = "Rang 3\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man 'Tödliche Navigation' effizienter verzaubert.\nEine Waffe dauerhaft verzaubern, sodass manchmal Euer kritischer Trefferwert 30 Sek. lang um 1 erhöht wird. Dieser Effekt ist bis zu 5-mal stapelbar. Beim Erreichen von 5 Stapeln werden alle Stapel aufgezehrt und Euer kritischer Trefferwert wird 10 Sek. lang um 9 erhöht.\n\nMaterialbedarf erheblich verringert.\nBenötigt Verzauberkunst von Kul Tiras (1)\nBenötigt Zandalariimperium\n- Respektvoll\nVerkaufspreis:" }
