entries[162725] = { ["name"] = "Formel: Waffe - Sturmkraftschlag", ["text"] = "Rang 3\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man 'Sturmkraftschlag' effizienter verzaubert.\nEine Waffe dauerhaft verzaubern, sodass sie eine Aura auslöst, die Euer Angriffstempo bei Nahkampf- oder Distanzangriffen und -fähigkeiten 15 Sek. lang um 15% erhöht.\n\nMaterialbedarf erheblich verringert.\nBenötigt Verzauberkunst von Kul Tiras (1)\nBenötigt Voldunai\n- Respektvoll\nVerkaufspreis:" }
entries[162726] = { ["name"] = "Formel: Waffe - Vielseitige Navigation", ["text"] = "Rang 3\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man 'Vielseitige Navigation' effizienter verzaubert.\nEine Waffe dauerhaft verzaubern, sodass manchmal Eure Vielseitigkeit 30 Sek. lang um 1 erhöht wird. Dieser Effekt ist bis zu 5-mal stapelbar. Beim Erreichen von 5 Stapeln werden alle Stapel aufgezehrt und Eure Vielseitigkeit wird 10 Sek. lang um 9 erhöht.\n\nMaterialbedarf erheblich verringert.\nBenötigt Verzauberkunst von Kul Tiras (1)\nBenötigt Voldunai\n- Respektvoll\nVerkaufspreis:" }
entries[162727] = { ["name"] = "Bauplan: Frostversetzte Munition", ["text"] = "Rang 3\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man frostversetzte Munition effizienter herstellt.\nVerringert erheblich die erforderlichen Materialien zur Herstellung von frostversetzter Munition.\nBenötigt Ingenieurskunst von Kul Tiras (1)\nBenötigt Voldunai\n- Respektvoll\nVerkaufspreis:\nFrostversetzte Munition\nBenutzen: Wertet dauerhaft die Munition einer Distanzwaffe auf, sodass Euer Ziel manchmal geringen Frostschaden erleidet und seine Bewegungsgeschwindigkeit für 3 Sek. um 20% verringert wird, wenn Ihr Distanzschaden verursacht.\n\nDurch das Anbringen dieser Vorrichtung an einer Distanzwaffe wird diese seelengebunden.\nVerkaufspreis:\nBenötigt Moneliterz (12), Chemische Sprengkapsel (5), Isoliertes Kabel (5)" }
