entries[162741] = { ["name"] = "Bauplan: Organische Diskombobulierungsgranate", ["text"] = "Rang 3\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man eine organische Diskombobulierungsgranate effizienter herstellt.\nVerringert erheblich die erforderlichen Materialien zur Herstellung einer organischen Diskombobulierungsgranate.\n\nChance, mehrere Bomben herzustellen.\nBenötigt Ingenieurskunst von Kul Tiras (1)\nBenötigt Zandalariimperium\n- Respektvoll\nVerkaufspreis:\nOrganische Diskombobulierungsgranate\nBenutzen: Wirft eine Bombe, die bei ihrer Detonation 5 mechanische Schafe beschwört. Gegner, die mit den Schafen in Kontakt kommen, werden für 20 Sek. verwandelt. Funktioniert nicht bei Zielen über Stufe 50. (1 Min Abklingzeit)\nVerkaufspreis:\nBenötigt Moneliterz (4), Chemische Sprengkapsel (2), Isoliertes Kabel (4)" }
entries[162742] = { ["name"] = "Bauplan: Interdimensionales Begleiterrepositorium", ["text"] = "Rang 3\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man ein interdimensionales Begleiterrepositorium effizienter herstellt.\nVerringert erheblich die erforderlichen Materialien zur Herstellung eines interdimensionalen Begleiterrepositoriums.\nBenötigt Ingenieurskunst von Kul Tiras (1)\nBenötigt Zandalariimperium\n- Respektvoll\nVerkaufspreis:\nInterdimensionales Begleiterrepositorium\nBenutzen: Beschwört einen tragbaren Stallmeister, mit dem Jäger bis zu 2 Min. lang interagieren können.\nVerkaufspreis:\nBenötigt Moneliterz (5), Sturmsilbererz (4), Isoliertes Kabel (5)" }
entries[162743] = { ["name"] = "Bauplan: Stationärer Umkleider", ["text"] = "Rang 3\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man einen stationären Umkleider effizienter herstellt.\nVerringert erheblich die erforderlichen Materialien zur Herstellung eines stationären Umkleiders.\nBenötigt Ingenieurskunst von Kul Tiras (1)\nBenötigt Zandalariimperium\n- Respektvoll\nVerkaufspreis:\nStationärer Umkleider\nBenutzen: Beschwört ein Gerät, mit dem Ihr das Aussehen Eurer Rüstung verändern könnt. Das Gerät bleibt bis zu 2 Min. lang bestehen.\n\"Hinweis: Aufgrund der Funktionsweise dieses Geräts sind leichte Kopfschmerzen, Übelkeit sowie Wechsel von Volkszugehörigkeit und/oder Geschlecht nicht auszuschließen. Mit Vorsicht zu verwenden.\"\nVerkaufspreis:\nBenötigt Moneliterz (5), Sturmsilbererz (4), Isoliertes Kabel (5)" }
entries[162744] = { ["name"] = "Bauplan: Monelitzielfernrohr des Eifers", ["text"] = "Rang 3\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man ein Monelitzielfernrohr des Eifers effizienter herstellt.\nVerringert erheblich die erforderlichen Materialien zur Herstellung eines Monelitzielfernrohrs des Eifers.\nBenötigt Ingenieurskunst von Kul Tiras (1)\nBenötigt Die Eidgebundenen\n- Respektvoll\nVerkaufspreis:\nMonelitzielfernrohr des Eifers\nBenutzen: Bringt dauerhaft eine spezielle Vorrichtung an einer Distanzwaffe an, sodass manchmal das Tempo 12 Sek. lang um 194 erhöht wird, wenn Ihr Distanzschaden verursacht.\n\nDurch das Anbringen der Vorrichtung an einer Distanzwaffe wird diese seelengebunden.\nVerkaufspreis:\nBenötigt Moneliterz (10), Sturmsilbererz (5)" }
entries[162745] = { ["name"] = "Bauplan: Präzisionsgesinnungswandler", ["text"] = "Rang 3\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man einen Präzisionsgesinnungswandler effizienter herstellt.\nVerringert erheblich die erforderlichen Materialien zur Herstellung eines Präzisionsgesinnungswandlers.\nBenötigt Ingenieurskunst von Kul Tiras (1)\nBenötigt Die Eidgebundenen\n- Respektvoll\nVerkaufspreis:\nPräzisionsgesinnungswandler\nWird beim Anlegen gebunden\nEinhändig Streitkolben\n4 - 5 Schaden Geschwindigkeit 2.60\n(1.7 Schaden pro Sekunde)\n+18 Intelligenz\n+5 Ausdauer\nHaltbarkeit 110 / 110\n\"Die optimale Nutzung sieht Hiebe vor, bis das Ziel keine Widerrede mehr bieten kann.\"\nVerkaufspreis:\nBenötigt Sturmsilbererz (20), Platinerz (8), Expulsom (5)\nOptionale Reagenzien: [] (#49)" }
entries[162746] = { ["name"] = "Bauplan: Präzise abgestimmter Sturmstahlvernichter", ["text"] = "Rang 3\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man einen präzise abgestimmten Sturmstahlvernichter effizienter herstellt.\nVerringert erheblich die erforderlichen Materialien zur Herstellung eines präzise abgestimmten Sturmstahlvernichters.\nBenötigt Ingenieurskunst von Kul Tiras (1)\nBenötigt Die Eidgebundenen\n- Respektvoll\nVerkaufspreis:\nHorde\nPräzise abgestimmter Sturmstahlvernichter\nWird beim Anlegen gebunden\nDistanz Schusswaffe\n14 Schaden Geschwindigkeit 3.00\n(4.7 Schaden pro Sekunde)\n+6 Beweglichkeit\n+9 Ausdauer\nHaltbarkeit 100 / 100\nVerkaufspreis:\nAllianz\nPräzise abgestimmter Sturmstahlvernichter\nWird beim Anlegen gebunden\nDistanz Schusswaffe\n14 Schaden Geschwindigkeit 3.00\n(4.7 Schaden pro Sekunde)\n+6 Beweglichkeit\n+9 Ausdauer\nHaltbarkeit 100 / 100\nVerkaufspreis:\nBenötigt Sturmsilbererz (20), Platinerz (8), Chemische Sprengkapsel (5), Expulsom (5)\nOptionale Reagenzien: [] (#49)" }
