entries[163020] = { ["name"] = "Bauplan: Diskombobulator des ehrenhaften Kämpfers", ["text"] = "Rang 2\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man einen Diskombobulator des ehrenhaften Kämpfers effizienter herstellt.\nVerringert die erforderlichen Materialien zur Herstellung eines Diskombobulators des ehrenhaften Kämpfers.\nBenötigt Ingenieurskunst von Kul Tiras (1)\nVerkaufspreis:\nDiskombobulator des ehrenhaften Kämpfers\nWird beim Anlegen gebunden\nEinhändig Streitkolben\n8 - 10 Schaden Geschwindigkeit 2.60\n(3.5 Schaden pro Sekunde)\n+3 Beweglichkeit\n+5 Ausdauer\nHaltbarkeit 90 / 90\n\"Sein Magnetismus zeigt sich primär darin, dass die Schädel von Gegnern in die Bahn seiner Hiebe gezogen werden.\"\nVerkaufspreis:\nBenötigt Sturmsilbererz (22), Platinerz (10), Expulsom (6)" }
